  'The Coach isn’t installed properly on this instance.': '이 인스턴스에 코치가 제대로 설치되어 있지 않습니다.',
  'The Coach couldn’t run. The instance owner needs to check its setup.': '코치를 실행하지 못했습니다. 인스턴스 소유자가 설정을 확인해야 합니다.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': '코치가 AI 제공업체의 한도에 도달했습니다. 나중에 다시 시도하거나 인스턴스 소유자가 요금제나 키를 확인해야 합니다.',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': '코치의 AI 제공업체가 요청 형식을 거부했습니다. 인스턴스 소유자가 다른 모델을 시도해야 합니다.',
  'The Coach’s AI provider is having an outage. Try again in a little while.': '코치의 AI 제공업체에 장애가 발생했습니다. 잠시 후 다시 시도하세요.',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': '코치가 AI 제공업체에 연결하지 못했습니다. 인스턴스 소유자가 엔드포인트와 네트워크를 확인해야 합니다.',
