  '{0} sets become {1}: one on each side, {2}s held every time.': '{0}세트가 {1}세트가 됩니다: 양쪽 각각 한 번씩, 매번 {2}초 유지.',
  'For side planks, single-arm holds and the like. Trains each side on its own.': '사이드 플랭크, 한 팔 버티기 같은 운동용이에요. 각 쪽을 따로 훈련해요.',
