  'openGym can no longer write to “{0}”, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym이 더 이상 “{0}”에 쓸 수 없어서 사본을 다시 Documents/openGym에 저장합니다. 그 폴더로 돌아가려면 다시 선택하세요.',
  'openGym can no longer write to the chosen folder, so copies go to Documents/openGym again. Choose the folder again to switch back.': 'openGym이 더 이상 선택한 폴더에 쓸 수 없어서 사본을 다시 Documents/openGym에 저장합니다. 그 폴더로 돌아가려면 다시 선택하세요.',
  // --- missed-workout nudge (lib/nudge.js; the push copy is mirrored in api/nudge-copy.js) ---
  'Nudge me when I skip a planned workout': '계획된 운동을 건너뛰면 알려 주기',
  'Nudge tone': '알림 말투',
  'Friendly': '다정하게',
  'Guilt trip': '죄책감 자극',
  'Drill sergeant': '훈련 교관',
  'One nudge in the evening of a planned day with nothing logged, between 20:00 and 21:30. After 3 missed days in a row it goes quiet until your next workout.': '계획된 날에 기록이 없으면 저녁 20:00~21:30 사이에 한 번 알려 드립니다. 3일 연속으로 건너뛰면 다음 운동까지 조용히 있습니다.',
  'Logged a workout on another device? Before the nudge goes out, the phone checks with your server whenever it lets the app run in the background. Opening the app always catches up.': '다른 기기에서 운동을 기록했나요? 휴대폰이 앱을 백그라운드에서 실행하게 해 주면, 알림을 보내기 전에 서버에 확인해요. 앱을 열면 언제나 최신 상태가 돼요.',
  'Everything okay?': '괜찮으세요?',
  '{0} is still waiting. What’s up?': '{0}이(가) 아직 기다리고 있어요. 무슨 일 있어요?',
  'No {0} today? Even a short session tomorrow counts.': '오늘은 {0} 안 했나요? 내일은 짧게라도 하면 돼요.',
  'Rough day? {0} will keep. Tomorrow is a fresh start.': '힘든 하루였나요? {0}은(는) 기다려 줄 거예요. 내일 다시 시작해요.',
  'Hey, {0} didn’t happen today. All good?': '저기요, 오늘 {0}을(를) 못 했네요. 괜찮아요?',
  'I miss you': '보고 싶어요',
  '{0} waited by the door all evening. For you.': '{0}이(가) 저녁 내내 문 앞에서 기다렸어요. 당신을요.',
  'The barbell asked about you today. I didn’t know what to say.': '오늘 바벨이 당신 안부를 물었어요. 뭐라고 해야 할지 몰랐어요.',
  'Was it something I said? {0} misses you.': '제가 뭐 잘못 말했나요? {0}이(가) 당신을 보고 싶어 해요.',
  'I saved you a spot on the bench. It’s still empty.': '벤치에 자리를 맡아 뒀어요. 아직 비어 있어요.',
  'Attention, recruit!': '차렷, 훈련병!',
  'Your gains are packing their bags. {0} tomorrow, no excuses!': '근손실이 짐을 싸고 있다. 내일 {0}, 핑계는 없다!',
  '{0} doesn’t do itself, recruit. Move it!': '{0}은(는) 저절로 되지 않는다, 훈련병. 움직여!',
  'Excuses don’t lift weights. Report for {0} tomorrow!': '핑계는 무게를 들지 않는다. 내일 {0}에 집합!',
  'Your muscles filed a missing-person report. Show up for {0}!': '근육들이 실종 신고를 냈다. {0}에 출석하라!',
  'That address answers, but it isn’t an openGym server. Check the URL.': '이 주소는 응답하지만 openGym 서버가 아닙니다. URL을 확인하세요.',
  'That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.': '이 주소는 응답하지만 openGym 대신 로그인 페이지나 프록시 규칙이 응답했습니다. /api/ 를 그대로 openGym까지 통과시켜 주세요. docs/SELF_HOSTING.md의 “Phone app and CORS”를 참고하세요.',
  'Switch sides': '방향 바꾸기',
  'Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.': '운동을 마치거나 루틴을 수정할 때마다 “{0}”에 날짜가 붙은 사본을 저장하고 최신 {1}개를 보관합니다.',
  'Saves a dated copy to the folder you chose after finishing a workout or editing a routine, and keeps the newest {0}.': '운동을 마치거나 루틴을 수정할 때마다 선택한 폴더에 날짜가 붙은 사본을 저장하고 최신 {0}개를 보관합니다.',
