  'Weight means': '무게 기준',
  'The weight of the one you hold. One arm, so it counts once.': '들고 있는 하나의 무게예요. 한 팔이라 한 번만 셉니다.',
  'The weight of one, so 20 means 20 in each hand. Volume counts both.': '하나의 무게라서 20은 양손에 20씩이에요. 볼륨은 두 개를 셉니다.',
