  // --- dumbbell inventory (#376) ---
  'You’ve outgrown the rack: {0} {1} is your heaviest dumbbell, so the weight stays.': '랙을 졸업했어요: 가장 무거운 덤벨이 {0} {1}이라 무게는 그대로예요.',
