  'To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:': '답하려면 코치가 이 내용을 내 openGym 서버를 통해, 서버 관리자가 고른 openGym 밖의 AI 서비스인 {0}에 보내요:',
  'To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:': '답하려면 이 기기가 이 내용을 내 API 키로, openGym 밖의 AI 서비스인 {0}에 직접 보내요:',
