  'Your answers to the Coach: goal, days, equipment, limits and injuries': '코치에게 한 답변: 목표, 요일, 장비, 제한 사항과 부상',
  'Your body weight and goal weight': '체중과 목표 체중',
  'Your data, your call': '내 데이터, 내 결정',
  'Your name, email and sign-in stay put. {0} handles the rest under its own privacy terms.': '이름, 이메일, 로그인 정보는 여기 남아요. 나머지는 {0}의 개인정보 처리 방침에 따라 처리돼요.',
  'Your plan: routines, exercises, sets, reps and schedule': '내 플랜: 루틴, 운동, 세트, 반복 횟수, 일정',
