  // --- reading back from Health Connect / Apple Health (v1.4.3) ---
  'Heart rate from your watch': '워치의 심박수',
  'After a workout, each set gets the heart rate your watch saved. Garmin, Fitbit, Galaxy Watch and friends welcome.': '운동이 끝나면 각 세트에 워치가 저장한 심박수가 들어가요. Garmin, Fitbit, Galaxy Watch 다 환영해요.',
  'Weigh-ins from other apps': '다른 앱의 체중 기록',
  'Your smart scale’s weigh-ins land here. One you type in yourself always wins.': '스마트 체중계의 기록이 여기로 와요. 직접 입력한 기록이 항상 이겨요.',
  'openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last 30 days. Older workouts stay as they are.': 'openGym은 열려 있을 때만 읽어요: 최근 하루 동안의 운동 심박수와 최근 30일의 체중 기록. 그보다 오래된 운동은 그대로 둬요.',
  // --- gym reminder (#614) ---
  'A nudge when you walk into your gym.': '헬스장에 들어서면 살짝 알려줘요.',
  'Add a gym': '헬스장 추가',
  'All the time': '항상 허용',
  'Allow location “All the time”?': '위치를 ‘항상 허용’할까요?',
  'Allow location “Always”?': '위치를 ‘항상’ 허용할까요?',
  'Always': '항상',
  'Finding you…': '위치 찾는 중…',
  'Gym reminder': '헬스장 알림',
  'Checking if you made it to the gym': '헬스장에 도착했는지 확인하는 중',
  'Quick arrival check': '빠른 도착 확인',
  'Near a gym, the phone takes a short GPS look (a few minutes at most) so the nudge comes at the door.': '헬스장 근처에서 휴대폰이 잠깐 GPS로 확인해요(길어야 몇 분). 그래서 알림이 문 앞에서 와요.',
  'Android can take up to half an hour to notice you walked in. Set openGym’s battery use to Unrestricted and the phone takes a short GPS look when you get near a gym, so the nudge comes at the door.': 'Android는 도착을 알아차리는 데 30분까지 걸릴 수 있어요. openGym의 배터리 사용을 제한 없음으로 바꾸면 헬스장 근처에서 잠깐 GPS로 확인해서 알림이 문 앞에서 와요.',
  'Gym spotted': '헬스장 발견',
  'Leave it empty for the default.': '비워 두면 기본 문구를 써요.',
  'Location access': '위치 접근',
  'Location isn’t allowed for openGym. You can change that in the phone’s settings.': 'openGym에 위치 권한이 없어요. 휴대폰 설정에서 바꿀 수 있어요.',
  'My gym': '내 헬스장',
  'Name': '이름',
  'No more nudges when you arrive here.': '여기 도착해도 더 이상 알리지 않아요.',
  'Not asked yet': '아직 묻지 않음',
  'Nothing found. Try a street and a town.': '결과가 없어요. 도로명과 도시로 검색해 보세요.',
  'Notification text': '알림 문구',
  'Notifications are off for openGym, so the reminder has nowhere to show up.': 'openGym 알림이 꺼져 있어서 알림이 뜰 곳이 없어요.',
  'On the next screen, pick “Allow all the time”.': '다음 화면에서 ‘항상 허용’을 고르세요.',
  'Only between certain hours': '특정 시간에만',
  'Only while using the app': '앱 사용 중에만',
  'Outside these hours the phone stays quiet, even at the gym.': '이 시간 밖에는 헬스장에 있어도 조용히 있어요.',
  'Radius': '반경',
  'Ready for your workout? 💪': '운동할 준비 됐나요? 💪',
  'Remove this gym?': '이 헬스장을 삭제할까요?',
  'Search': '검색',
  'Searching…': '검색 중…',
  'That’s 20 gyms, the most a phone can watch.': '헬스장 20곳, 휴대폰이 지켜볼 수 있는 최대치예요.',
  'The phone itself watches the gyms you added and only wakes openGym when you arrive. No tracking in between, and your locations never leave this phone.': '추가한 헬스장은 휴대폰이 직접 지켜보고, 도착했을 때만 openGym을 깨워요. 그 사이 추적은 없고, 위치는 이 휴대폰 밖으로 나가지 않아요.',
  'The reminder needs location access in the background. You can allow it in the phone’s settings.': '알림에는 백그라운드 위치 권한이 필요해요. 휴대폰 설정에서 허용할 수 있어요.',
  'To notice that you walked into your gym while openGym is closed, the phone needs to let it see your location in the background.': 'openGym이 닫혀 있을 때 헬스장에 들어온 걸 알아채려면, 휴대폰이 백그라운드에서 위치를 볼 수 있게 해 줘야 해요.',
  'Until': '종료',
  'Walk into one of your gyms and openGym nudges you to hit Start. Once a day at most, and never when you already trained. Your gyms stay on this phone.': '헬스장에 들어서면 openGym이 시작을 누르라고 살짝 알려줘요. 하루 한 번까지, 이미 운동했다면 알리지 않아요. 헬스장 정보는 이 휴대폰에만 있어요.',
  'Without background location the phone can’t spot your gym while openGym is closed.': '백그라운드 위치가 없으면 openGym이 닫혀 있을 때 헬스장을 알아챌 수 없어요.',
  'Your gyms': '내 헬스장 목록',
  '{0} m': '{0}m',
  'Precise location is off for openGym. Turn it on in the phone’s settings, or your gym can’t be spotted.': 'openGym의 정확한 위치가 꺼져 있어요. 휴대폰 설정에서 켜야 헬스장을 알아챌 수 있어요.',
