  "This lives in the openGym phone app.": "이건 휴대폰의 openGym 앱에 있어요.",
  "Your watch or scale writes here too? Garmin, COROS, Fitbit, Withings, Oura and friends reach openGym this way.": "시계나 체중계도 여기에 기록하나요? Garmin, COROS, Fitbit, Withings, Oura 등은 이렇게 openGym에 들어와요.",
  "Now in Integrations": "이제 연동에 있어요",
  "Not on this phone": "이 휴대폰에서는 안 돼요",
