  "AI & API": "AI 및 API",
  "Workouts and weigh-ins out, heart rate and scale readings in.": "운동과 체중은 내보내고, 심박수와 체중계 값은 가져와요.",
  "Finished workouts and weigh-ins go to Apple Health.": "끝낸 운동과 체중이 Apple Health로 가요.",
  "Heart rate from your watch fills in each set.": "시계의 심박수가 세트마다 채워져요.",
