  "A signed JSON message when a workout is finished, a record falls or you weigh in.": "운동이 끝나거나 기록이 깨지거나 체중을 재면 서명된 JSON 메시지를 보내요.",
  "Sent by your server, from whichever device you logged on.": "어느 기기에서 기록했든 서버가 보내요.",
