  // --- tour v2: ways between screens and the tutorials ---
  "A new routine": "새 루틴 하나",
  "A photo or video": "사진이나 동영상",
  "Add an exercise first, then it’s worth saving.": "먼저 운동을 하나 넣어야 저장할 맛이 나요.",
  "Add exercises": "운동 넣기",
  "Add it to the loop": "로테이션에 넣기",
  "An exercise’s history, records and progress are worked out from your workouts. Fix the workout and they follow.": "운동의 기록, 최고 기록, 진행 상황은 내 운동에서 계산돼요. 운동을 고치면 알아서 따라와요.",
  "Back home, practice over. Stats is where the gains pile up. Tap it.": "홈으로 돌아왔어요, 연습 끝. '통계'에 성과가 쌓여요. 눌러 보세요.",
  "Back it all up": "전부 백업하기",
  "Back to Stats": "통계로 돌아가기",
  "Backups, spreadsheets, other apps and sync": "백업, 스프레드시트, 다른 앱, 동기화",
  "Body part": "신체 부위",
  "Build your first plan": "첫 계획 만들기",
  "Call it what you call it. Other names you add help the search find it.": "평소 부르는 이름으로 지으세요. 다른 이름을 더 넣으면 검색이 더 잘 찾아요.",
  "Change them any time in Plan. Past workouts keep what you actually did.": "'계획'에서 언제든 바꿀 수 있어요. 지난 운동은 실제로 한 그대로 남아요.",
  "Create it": "만들기",
  "Custom exercises live with the rest. Tap Exercises.": "직접 만든 운동도 다른 운동과 같이 있어요. '운동'을 누르세요.",
  "Date & time": "날짜와 시간",
  "Edit a workout": "운동 고치기",
  "Edit your data": "내 데이터 고치기",
  "Every exercise is one tap away. Tap Exercises.": "모든 운동이 탭 한 번 거리에 있어요. '운동'을 누르세요.",
  "Every weigh-in": "모든 체중 기록",
  "Every workout you’ve logged. Tap the clock.": "지금까지 기록한 모든 운동. 시계를 누르세요.",
  "Everything you can tweak hides behind this little gear. Tap it.": "바꿀 수 있는 건 전부 이 작은 톱니바퀴 뒤에 숨어 있어요. 눌러 보세요.",
  "Export & import": "내보내기와 가져오기",
  "Felt strong. Probably the coffee.": "힘이 넘쳤다. 아마 커피 덕분.",
  "Fine-tune it": "다듬기",
  "Fix a weigh-in": "체중 기록 고치기",
  "Forgot one?": "하나 빼먹었나요?",
  "Hands-free backups": "알아서 되는 백업",
  "Head back to Home first. Tap it.": "먼저 '홈'으로 돌아가요. 눌러 보세요.",
  "Health apps": "건강 앱",
  "Here’s the pretend one. Tap it.": "이게 가짜 운동이에요. 눌러 보세요.",
  "Home shows it on its day and Start opens it. Change it any time right here.": "'홈'이 그날 보여 주고 '시작'이 열어 줘요. 언제든 여기서 바꿀 수 있어요.",
  "It starts today’s plan, or lets you pick something else. Tap it for a practice run.": "오늘 계획을 시작하거나 다른 걸 고르게 해 줘요. 연습 삼아 눌러 보세요.",
  "Its own page": "전용 페이지",
  "It’s the first row of the list. Tap it.": "목록의 첫 줄이에요. 눌러 보세요.",
  "Log a past workout with its own date and time. It counts like any other.": "날짜와 시간을 정해서 지난 운동을 기록하세요. 다른 운동이랑 똑같이 쳐줘요.",
  "Measurements and photos": "신체 치수와 사진",
  "Missing one? Make it. It works like any other: routines, workouts, records, the body map, backups and sync. Nothing is created until you tap Create.": "없는 운동이 있나요? 만드세요. 다른 운동이랑 똑같이 쓰여요: 루틴, 운동, 기록, 신체 지도, 백업, 동기화. '운동 만들기'를 누르기 전까진 아무것도 안 만들어져요.",
  "Moving in?": "이사 오셨나요?",
  "Name a routine, add exercises, give it a day": "루틴 이름 짓고, 운동 넣고, 요일 정하기",
  "Name it": "이름 짓기",
  "Name, muscles, equipment and a photo": "이름, 근육, 장비, 사진",
  "New routines start on the Routines side. Tap Routines.": "새 루틴은 '루틴' 쪽에서 시작해요. '루틴'을 누르세요.",
  "Notes": "메모",
  "Now give it a day. Tap back to Plan.": "이제 요일을 정해 줘요. 뒤로 눌러 '계획'으로 가세요.",
  "Now your workouts": "이제 내 운동",
  "Off to Plan": "계획으로 가기",
  "One file with everything. Keep it somewhere safe, Import backup brings it back.": "모든 게 담긴 파일 하나. 안전한 곳에 두세요, '백업 가져오기'로 되살릴 수 있어요.",
  "One more": "하나만 더",
  "Open a check-in to change or delete it. Progress photos work the same way.": "측정 기록을 열면 바꾸거나 지울 수 있어요. 진행 사진도 똑같아요.",
  "Open a workout": "운동 열기",
  "Optional: your own picture or clip of the setup. Handy for that one weird machine.": "선택 사항: 기구 세팅을 찍은 사진이나 영상. 그 이상한 기계 하나엔 딱이에요.",
  "Pick a backup file and it’s all back.": "백업 파일을 고르면 전부 돌아와요.",
  "Pick one. Muscle groups are optional, but they feed the body map and muscle balance.": "하나 고르세요. 근육 그룹은 선택이지만, 신체 지도와 근육 균형에 쓰여요.",
  "Pick your exercises": "운동 고르기",
