  "As a routine they can do too": "친구도 할 수 있는 루틴으로",
  "Nothing to share in this one.": "여기엔 공유할 게 없어요.",
  "Link copied. Paste it to a friend.": "링크를 복사했어요. 친구에게 붙여 넣으세요.",
  "That one’s too big for a link, so it goes as a plan file.": "링크로 보내기엔 너무 커서 플랜 파일로 보내요.",
  "Here’s my {0} on openGym 💪": "openGym에서 하는 내 {0} 💪",
  "Couldn’t make a link for this one.": "이 루틴의 링크를 만들지 못했어요.",
  "A link to “{0}”. Your friend taps it and adds it to their own openGym. The routine rides inside the link, no server in between.": "“{0}” 링크예요. 친구가 탭하면 자기 openGym에 추가돼요. 루틴은 링크 안에 담겨 가고, 중간에 서버는 없어요.",
  "Include my weights": "내 무게 포함",
  "Off: just sets, reps and rest. They pick their own weights.": "끄면 세트, 횟수, 휴식만 보내요. 무게는 친구가 정해요.",
  "So they know who it’s from.": "누가 보냈는지 알 수 있게요.",
  "Share link": "링크 공유",
  "From {0}": "{0} 님이 보냄",
  "Added as a new routine. Nothing you already have is touched.": "새 루틴으로 추가돼요. 이미 있는 건 건드리지 않아요.",
  "Add to my routines": "내 루틴에 추가",
  "Added to your routines": "루틴에 추가했어요",
  "This link is from a newer openGym. Update the app to open it.": "더 새로운 openGym에서 만든 링크예요. 앱을 업데이트하고 열어 주세요.",
  "This browser can’t open this link. Try it in the openGym app.": "이 브라우저는 이 링크를 열 수 없어요. openGym 앱에서 열어 보세요.",
