  "Upper-body enthusiast": "상체 마니아",
  "Chest, shoulders, arms. The mirror approves.": "가슴, 어깨, 팔. 거울이 인정했어요.",
  "Steady and sure": "꾸준함 그 자체",
  "No drama, just showing up. That is how it is done.": "드라마 없이 그냥 나타났어요. 원래 그렇게 하는 거예요.",
