  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "불편하니 남은 세트는 가볍게 하세요. 계속 아프면 멈추세요.",
  "It pinches, so the sets you have left go to a movement that loads the same muscle from a kinder angle.": "불편하니 남은 세트는 같은 근육을 더 편한 각도로 쓰는 동작으로 옮깁니다.",
