  "Festive flame on. Your streak looks very merry.": "축제의 불꽃 켜짐. 연속 기록이 아주 흥겨워 보여요.",
  "Halloween and friends, little extras for the time of year. All optional.": "할로윈과 친구들, 계절 분위기를 내는 작은 덤이에요. 전부 선택 사항이에요.",
