  "Missed a day? Its door waits for you.": "하루 놓쳤나요? 그 문은 기다려 줘요.",
  "Not quite a reindeer yet. Plenty of December left.": "아직 순록은 아니에요. 12월은 넉넉히 남았어요.",
  "Open door {0}": "{0}번째 문 열기",
  "Put it on": "착용하기",
  "Spread them over the day. Every {0} counts.": "하루에 나눠서 하세요. {0}마다 다 쳐줘요.",
  "Start a workout with it": "이걸로 운동 시작하기",
  "Start the finisher": "피니셔 시작",
  "Swipe the door open, or give it a tap": "문을 스와이프해서 열거나 한 번 탭해 보세요",
  "Take {0} back": "{0} 빼기",
  "Time trained: {0}": "운동 시간: {0}",
  "Train today, or do this, and its bauble lights up.": "오늘 운동하거나 이걸 하면 오너먼트에 불이 켜져요.",
  "Wearing it. Very merry.": "착용 중이에요. 아주 흥겨워요.",
  "Weeks in a row with at least one workout. The elves are taking notes.": "운동을 한 번 이상 한 주가 연속으로 몇 주인지 보여 줘요. 엘프들이 받아 적는 중이에요.",
  "Your longest streak in {0}": "{0}년 가장 긴 연속 기록",
  "Your most trained muscle in {0}": "{0}년에 가장 많이 운동한 근육",
  "Your present: a festive flame": "선물이 도착했어요: 축제의 불꽃",
  "Your streak wears a Santa hat, all year if you like. Change it any time in Settings, Icons.": "연속 기록이 산타 모자를 써요. 원하면 1년 내내요. 설정, 아이콘에서 언제든 바꿀 수 있어요.",
  "{0}% of all the work you did. Clearly a favourite.": "전체 운동량의 {0}%. 확실히 가장 아끼는 운동이네요.",
  "Quick finisher": "빠른 피니셔",
