  "Jingle burner": "징글 버너",
  "Sleigh pull": "썰매 끌기",
  "Snow day plank": "눈 오는 날 플랭크",
  "Chimney climb": "굴뚝 오르기",
  "Elf on the floor": "바닥 위의 엘프",
  "Last-minute dash": "막판 질주",
  "Knees on the floor count just the same.": "무릎을 바닥에 대도 똑같이 쳐줘요.",
  "Carry the shopping like it owes you money. Tall chest, slow steps.": "장바구니를 빚쟁이 대하듯 들어요. 가슴은 펴고 걸음은 천천히.",
  "You found Rudolph! He says hi and hides again. New spot tomorrow.": "루돌프를 찾았어요! 인사하고 다시 숨었어요. 내일은 새로운 곳이에요.",
  "{0} bauble on the tree, {1} lit": "트리에 오너먼트 {0}개, {1}개 켜짐",
  "{0} baubles on the tree, {1} lit": "트리에 오너먼트 {0}개, {1}개 켜짐",
  "About {0} minute, two moves back to back": "약 {0}분, 동작 두 개를 연달아",
  "About {0} minutes, two moves back to back": "약 {0}분, 동작 두 개를 연달아",
  "That is about {0} reindeer. Rudolph would like a lie-down.": "순록 약 {0}마리 분량이에요. 루돌프가 좀 누워야겠어요.",
  "Choose a photo": "사진 선택",
  "Drag to move, pinch or slide to zoom.": "드래그해서 옮기고, 핀치하거나 슬라이더로 확대하세요.",
  "Frame your best side": "가장 멋진 각도를 찾아보세요",
  "Only you see it, and it stays on this device.": "나만 볼 수 있고, 이 기기에만 저장돼요.",
  "Only you see it, here and on your other devices. Not even an admin can.": "나만 볼 수 있어요. 여기서도, 내 다른 기기에서도. 관리자도 못 봐요.",
  "Photo crop. Arrow keys move it, plus and minus zoom.": "사진 자르기. 화살표 키로 옮기고, 플러스와 마이너스로 확대해요.",
  "Picture removed. Back to the letter.": "사진을 지웠어요. 다시 이니셜이에요.",
  "Picture set. Looking sharp.": "사진을 설정했어요. 멋져요.",
  "Profile picture": "프로필 사진",
  "Remove picture": "사진 지우기",
  "That isn’t a photo. Try a JPEG, PNG, WebP or HEIC.": "사진이 아니에요. JPEG, PNG, WebP 또는 HEIC를 써 보세요.",
  "Use this photo": "이 사진 쓰기",
  "Zoom": "확대",
  "Missed plan": "놓친 계획",
  "Open this day": "이 날 열기",
  "Planned, not trained. Any other day this week still counts.": "계획했지만 운동하지 않았어요. 이번 주 다른 날에 해도 인정돼요.",
  "Planned, not trained. Any workout that week would have counted.": "계획했지만 운동하지 않았어요. 그 주에 아무 날이나 운동했으면 인정됐을 거예요.",
  "Planned, not trained. No harm done: you trained another day that week, so it still counts.": "계획했지만 운동하지 않았어요. 괜찮아요: 다른 날 운동해서 그 주는 인정돼요.",
  "Bank 1 freeze, earned every 4 trained weeks. Two missed weeks in a row end the streak.": "동결권 1개 보관, 운동한 주 4번마다 1개. 2주 연속 놓치면 연속 기록이 끝나요.",
  "Bank up to 2 freezes, one every 4 trained weeks. Even two missed weeks in a row can be covered.": "동결권 최대 2개 보관, 운동한 주 4번마다 1개. 2주 연속 놓쳐도 지킬 수 있어요.",
  "Change the freeze rule": "동결권 규칙 바꾸기",
  "Every 4th week you train earns a freeze. You can bank 1.": "운동한 주가 4번 쌓일 때마다 동결권 1개를 받아요. 1개까지 모을 수 있어요.",
  "Every week counts. Miss one and the streak starts over.": "매주가 중요해요. 한 주 놓치면 처음부터 다시 시작해요.",
  "From now on: {0}.": "이제부터: {0}.",
  "From the week of {0} on: {1}.": "{0} 주부터: {1}.",
  "Generous": "넉넉하게",
  "Gentle": "부드럽게",
  "How forgiving should your week streak be?": "주간 연속 기록을 얼마나 너그럽게 할까요?",
  "How strict should your streak be?": "연속 기록을 얼마나 엄격하게 할까요?",
  "Miss a week and a freeze covers it: the streak keeps going, that week just adds nothing. Two missed weeks in a row, and it starts over.": "한 주를 놓쳐도 동결권이 지켜 줘요: 기록은 이어지고, 그 주만 더해지지 않아요. 2주 연속 놓치면 처음부터 다시 시작해요.",
  "No freezes": "동결권 없음",
  "No freezes on your rule. Every week counts.": "내 규칙에는 동결권이 없어요. 매주가 중요해요.",
  "No freezes on your rule: a week without a workout starts it over.": "내 규칙에는 동결권이 없어요: 운동 없는 주가 있으면 처음부터 다시 시작해요.",
  "No workout, and your rule has no freezes, so the streak started over.": "운동이 없었고 내 규칙에는 동결권이 없어서 연속 기록이 다시 시작됐어요.",
  "Weeks already counted stay as they are.": "이미 계산된 주는 그대로예요.",
  "You can change it later in Settings. A change counts from then on.": "나중에 설정에서 바꿀 수 있어요. 바꾸면 그때부터 적용돼요.",
  "Your rule right now: {0}.": "지금 규칙: {0}.",
  "Your streak counts weeks with at least one workout. Freezes can cover the odd missed week.": "연속 기록은 운동을 한 번 이상 한 주를 세요. 동결권은 가끔 놓친 주를 지켜 줘요.",
  "{0} since the week of {1}.": "{1} 주부터 {0}.",
  "This phone has no print service. Turn one on in its settings and try again.": "이 휴대폰에는 인쇄 서비스가 없어요. 설정에서 하나를 켜고 다시 시도해 주세요.",
