  "{0} sees only what is on here.": "{0}님은 여기서 켜 둔 것만 볼 수 있어요.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "이 트레이너는 여기서 표시한 항목을 볼 수 있고, ‘제안’이나 ‘바로 수정’으로 표시한 항목은 수정할 수도 있어요. 트레이너가 헬스장 소속이면, 그 헬스장의 관리자는 ‘헬스장 관리자’ 줄에 표시한 항목을 볼 수 있지만 보기 이상은 절대 안 돼요. 이 설정은 언제든 바꾸거나 연결을 해제할 수 있고, 해제하는 즉시 효력이 멈춰요. 모든 열람과 수정은 공유 기록에 남고, 이 기록은 나만 읽을 수 있어요.",
