  "Keep training together privately? Your sharing stays as it is, without the gym lead. Until {0}, then it ends by itself.": "함께 비공개로 계속 운동할까요? 공유는 그대로 유지되고 헬스장 관리자만 빠져요. {0}까지이고, 그 뒤에는 저절로 끝나요.",
  "Kept. It starts once they may train privately here.": "유지했어요. 상대가 여기서 비공개로 운동할 수 있게 되면 시작돼요.",
