  "Shared by people on {0}. Take a copy, it is yours.": "{0} 사람들이 공유했어요. 사본을 가져가세요, 이제 내 거예요.",
  "Shared. Your gym thanks you.": "공유했어요. 헬스장이 고마워해요.",
  "Sharing is paused for your account on this server. Questions? Ask the admin.": "이 서버에서 내 계정의 공유가 일시 중지됐어요. 궁금한 점은 관리자에게 물어보세요.",
  "Sharing works once you are connected to a server.": "서버에 연결되면 공유할 수 있어요.",
  "Sharing…": "공유하는 중…",
