  "Taking…": "가져오는 중…",
  "Tell us what is up. Only the admins see it, not {0}.": "무슨 일인지 알려 주세요. 관리자만 볼 수 있고 {0}에게는 보이지 않아요.",
  "Thanks. An admin will take a look.": "고마워요. 관리자가 확인할게요.",
  "That did not work. Try again in a moment.": "잘 안 됐어요. 잠시 뒤에 다시 해 보세요.",
  "That file can never be shared here. Pictures and animations from the built-in library are licensed.": "이 파일은 여기서 절대 공유할 수 없어요. 기본 라이브러리의 그림과 애니메이션은 라이선스가 있어요.",
  "That file still carries hidden details like a location. Add it again in the app and share the new copy.": "이 파일에 아직 위치 같은 숨은 정보가 있어요. 앱에서 다시 추가한 뒤 새 사본을 공유해 주세요.",
  "That is not shared any more.": "더 이상 공유되지 않는 항목이에요.",
  "That one is not in the community any more.": "더 이상 커뮤니티에 없는 항목이에요.",
  "That one is yours.": "내 것이에요.",
  "That sound did not come through.": "소리가 제대로 전달되지 않았어요.",
  "That tip did not come through.": "팁이 제대로 전달되지 않았어요.",
  "The sharing text changed. Have a quick read and try again.": "공유 안내문이 바뀌었어요. 빠르게 읽어 보고 다시 해 보세요.",
  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "이 서버의 모든 사람에게 공개돼요. 여기에 계정이 있는 사람은 누구나 보고, 써 보고, 복사할 수 있어요. 내 이름과 날짜가 항상 함께 표시돼요. 내 것만 공유하세요. 직접 만들었거나 녹화했거나 넘겨줄 권리가 있는 것이요. 기본 라이브러리의 운동 그림과 애니메이션은 라이선스가 있어서 절대 공유할 수 없어요. 공유는 언제든 중지할 수 있고, 다른 사람이 이미 가져간 사본은 그 사람에게 남아요.",
  "This kind of item cannot be taken.": "이 종류의 항목은 가져올 수 없어요.",
  "This server has no community library.": "이 서버에는 커뮤니티 라이브러리가 없어요.",
  "Tick that it is yours to share first.": "먼저 공유해도 되는 내 것이라고 체크해 주세요.",
  "Tips": "팁",
  "Tips from your gym": "내 헬스장의 팁",
