  "Your exercises can move at {0} px instead of {1} px, crisp on this screen.": "운동 동작을 {1} px 대신 {0} px로, 이 화면에서 선명하게 볼 수 있어요.",
  "A one-time download of about {0} from Google Play, over Wi-Fi. It stays on this phone.": "Wi-Fi로 Google Play에서 약 {0}를 한 번만 받아요. 이 휴대폰에 남아요.",
  "A one-time download from Google Play, over Wi-Fi. It stays on this phone.": "Wi-Fi로 Google Play에서 한 번만 받아요. 이 휴대폰에 남아요.",
  "Download": "다운로드",
  "Changed your mind? Settings has it, any time.": "\ub9c8\uc74c\uc774 \ubc14\ub00c\uc5c8\ub098\uc694? \uc124\uc815\uc5d0\uc11c \uc5b8\uc81c\ub4e0 \ubc14\uafc0 \uc218 \uc788\uc5b4\uc694.",
  "A profile here already uses that e-mail. Sign in to it another way, then link {0} in Settings.": "이 이메일을 쓰는 프로필이 이미 있어요. 다른 방법으로 그 프로필에 로그인한 뒤 설정에서 {0}을(를) 연결하세요.",
  "Admin? Use your passkey": "관리자인가요? 패스키를 쓰세요",
  "Confirm with {0}": "{0}(으)로 확인",
  "Confirmed. Go ahead.": "확인됐어요. 계속하세요.",
  "Link": "연결",
  "Link your {0} account and sign in with it from now on. Your passkeys keep working too. First a quick check that this is really you.": "{0} 계정을 연결하고 앞으로 그걸로 로그인하세요. 패스키도 계속 쓸 수 있어요. 먼저 정말 본인인지 빠르게 확인할게요.",
  "Linked. You can sign in with {0} from now on.": "연결됐어요. 이제 {0}(으)로 로그인할 수 있어요.",
  "Linked. {0} signs you in here.": "연결됨. {0}(으)로 여기에 로그인돼요.",
  "Not linked yet.": "아직 연결 안 됨.",
  "Off to {0}…": "{0}(으)로 이동 중…",
  "Sign in with your provider again first, then try once more.": "먼저 제공자에서 다시 로그인한 뒤 한 번 더 시도하세요.",
  "Sign in with {0}": "{0}(으)로 로그인",
  "Sign-in cancelled. No harm done.": "로그인을 취소했어요. 아무 문제 없어요.",
  "That sign-in took too long or came from another tab. Give it another go.": "로그인이 너무 오래 걸렸거나 다른 탭에서 왔어요. 다시 시도해 주세요.",
  "That was a different {0} account than the one linked to this profile.": "이 프로필에 연결된 것과 다른 {0} 계정이었어요.",
  "That {0} account is already linked to another profile here.": "그 {0} 계정은 이미 여기의 다른 프로필에 연결돼 있어요.",
  "This profile is already linked to a {0} account.": "이 프로필은 이미 {0} 계정에 연결돼 있어요.",
  "This profile is linked to your {0} account, so signing in there signs you in here.": "이 프로필은 내 {0} 계정에 연결돼 있어요. 거기서 로그인하면 여기서도 로그인돼요.",
  "This server is invite-only and {0} alone does not get you in. Ask whoever runs it.": "이 서버는 초대제라 {0}만으로는 들어올 수 없어요. 운영자에게 물어보세요.",
  "This server signs everyone in with {0}. New here? Signing in makes your profile.": "이 서버에서는 모두 {0}(으)로 로그인해요. 처음인가요? 로그인하면 프로필이 만들어져요.",
  "This server signs people in with {0}.": "이 서버는 {0}(으)로 로그인해요.",
  "Too many attempts. Try again in a minute.": "시도가 너무 많아요. 1분 뒤에 다시 해 보세요.",
  "Unlink": "연결 해제",
  "Unlinked. {0} no longer signs you in here.": "연결을 해제했어요. 이제 {0}(으)로 여기에 로그인되지 않아요.",
  "or use a pairing code": "또는 페어링 코드 사용",
  "{0} could not be reached. Try again in a moment.": "{0}에 연결할 수 없어요. 잠시 후 다시 시도하세요.",
  "{0} is the only way into this profile, so it stays linked. Add a passkey first.": "{0}이(가) 이 프로필에 들어오는 유일한 방법이라 연결이 유지돼요. 먼저 패스키를 추가하세요.",
  "{0} let you in, but this server only takes certain groups. Ask whoever runs it to add you.": "{0}은(는) 통과시켰지만 이 서버는 특정 그룹만 받아요. 운영자에게 추가해 달라고 하세요.",
  "{0} sent back something we could not verify, so nobody was signed in. If it keeps happening, the admin page shows why.": "{0}이(가) 확인할 수 없는 응답을 보내서 아무도 로그인되지 않았어요. 계속 그렇다면 관리자 페이지에 이유가 나와요.",
