  "Life Fitness, Technogym… (optional)": "Life Fitness, Technogym… (선택)",
  "Same brand at another gym? It shares these numbers. Records and Stats still count every gym.": "다른 헬스장에 같은 브랜드가 있나요? 이 기록을 함께 써요. 기록과 통계는 여전히 모든 헬스장을 합쳐요.",
  "For machines and cables that feel different from gym to gym. Free weights rarely need it.": "헬스장마다 느낌이 다른 머신과 케이블용이에요. 프리웨이트는 거의 필요 없어요.",
  "All gyms": "모든 헬스장",
  "Today’s planned rows for {0} didn’t fit, so the routine’s own are up: {1}": "{0}에 계획된 세트가 맞지 않아서 루틴의 세트를 쓸게요: {1}",
  "Today’s rows come from {0}. Your routine stays as it is.": "오늘 세트는 {0}에서 왔어요. 루틴은 그대로예요.",
