  "Body fat, lean mass, bone mass, body water and BMR, as your scale saved them. Shown under Body measurements, never mixed into what you log.": "체지방, 제지방량, 골량, 체수분, 기초대사량을 체중계가 저장한 그대로 보여줘요. 신체 치수 아래에 표시되고, 직접 기록한 값과 섞이지 않아요.",
