  "Check the connection": "연결 확인",
  "Connect Strava once from openGym in a browser, signed in to your server. Your workouts then go up from the server, whichever device you log them on.": "브라우저에서 내 서버에 로그인한 채로 openGym에서 Strava를 한 번만 연결하세요. 그다음부터는 어느 기기에서 기록하든 서버가 운동을 올려 줘요.",
