  "Seconds for each part of a rep: lower, pause, lift, squeeze. 3-1-1-0 is three down, one at the bottom, one up, straight into the next.": "반복 한 번의 각 구간 초: 내리기, 멈춤, 들기, 쥐어짜기. 3-1-1-0은 3초 내리고, 바닥에서 1초, 1초 올리고, 바로 다음 반복으로.",
  "Show finished workouts too": "끝난 운동도 표시",
  "Strava connected. Your next workout goes up by itself.": "Strava 연결 완료. 다음 운동은 알아서 올라가요.",
  "Strava disconnected": "Strava 연결 해제됨",
  "Strava is listening": "Strava가 듣고 있어요",
  "Strava is off on this server. Register a Strava API app, then add strava to INTEGRATIONS and its STRAVA_CLIENT_ID and STRAVA_CLIENT_SECRET to the .env, and restart.": "이 서버에서는 Strava가 꺼져 있어요. Strava API 앱을 등록한 다음 INTEGRATIONS에 strava를, .env에 STRAVA_CLIENT_ID와 STRAVA_CLIENT_SECRET을 추가하고 다시 시작하세요.",
  "Strava uploads come from your own openGym server, so they need one. Connect this device to it in Account.": "Strava 업로드는 내 openGym 서버에서 나가니 서버가 필요해요. 계정에서 이 기기를 서버에 연결하세요.",
  "Strength workouts too": "근력 운동도",
  "Subscribe to this link in your calendar app. Anyone with it sees your plan, so keep it to yourself.": "이 링크를 캘린더 앱에서 구독하세요. 링크를 가진 사람은 누구나 계획을 볼 수 있으니 혼자만 간직하세요.",
  "Tempo": "템포",
  "Tempo for this set": "이 세트의 템포",
  "Tempo {0}": "템포 {0}",
  "Tempo {0}, start the guide": "템포 {0}, 가이드 시작",
  "The calendar link is served by your own openGym server, so it needs one. Connect this device to it in Account.": "캘린더 링크는 내 openGym 서버가 제공하니 서버가 필요해요. 계정에서 이 기기를 서버에 연결하세요.",
  "The link stops working at once. What your calendar already shows may stay until it refreshes.": "링크는 바로 작동을 멈춰요. 캘린더에 이미 보이는 일정은 새로 고칠 때까지 남아 있을 수 있어요.",
  "The old link stops working, and every calendar that uses it needs the new one.": "예전 링크는 작동을 멈추고, 그 링크를 쓰는 모든 캘린더에 새 링크가 필요해요.",
  "The password stays on this device, in its secure storage. It is never synced or put in a backup.": "비밀번호는 이 기기의 보안 저장소에만 남아요. 동기화되거나 백업에 들어가는 일은 없어요.",
