  // --- Settings → Garmin (garmin-146) ---
  "This version of openGym comes without the Garmin link, since Garmin’s part of it isn’t open source. The App Store, Google Play and GitHub versions have it.": "이 버전의 openGym에는 Garmin 연결이 없어요. Garmin 쪽 부분이 오픈 소스가 아니라서요. App Store, Google Play, GitHub 버전에는 있어요.",
  "Garmin Connect isn’t on this phone. Install it, pair your watch there, then come back here.": "이 휴대폰에 Garmin Connect가 없어요. 설치하고 거기서 시계를 페어링한 다음 다시 와 주세요.",
  "Garmin Connect needs an update before openGym can talk to your watch.": "openGym이 시계와 대화하려면 먼저 Garmin Connect를 업데이트해야 해요.",
  "Couldn’t reach Garmin Connect. Try again in a moment.": "Garmin Connect에 연결할 수 없어요. 잠시 후 다시 시도해 주세요.",
  "Pick your Garmin in Garmin Connect and your workouts show up on your wrist.": "Garmin Connect에서 Garmin을 고르면 운동이 손목에 나타나요.",
  "Garmin Connect doesn’t know a watch yet. Pair yours there first.": "Garmin Connect가 아직 아는 시계가 없어요. 먼저 거기서 시계를 페어링하세요.",
  "openGym is on your Garmin. Sets you log on the wrist land here.": "openGym이 Garmin에 있어요. 손목에서 기록한 세트가 여기로 와요.",
  "openGym is on your Garmin. It catches up as soon as the watch is in reach.": "openGym이 Garmin에 있어요. 시계가 가까이 오면 바로 따라잡아요.",
  "Your Garmin is here, openGym isn’t on it yet. Get it, then open it once on the watch.": "Garmin은 있는데 아직 openGym이 없어요. 설치하고 시계에서 한 번 열어 주세요.",
  "Not in reach": "범위 밖",
  "openGym isn’t on it yet": "아직 openGym이 없어요",
  "Your Garmins": "내 Garmin",
  "Choose watches": "시계 선택",
  "Look again": "다시 찾기",
  "Get openGym for Garmin": "Garmin용 openGym 받기",
  "Start a workout on the phone and your Garmin asks to open openGym.": "휴대폰에서 운동을 시작하면 Garmin이 openGym을 열지 물어봐요.",
