  "You were sick, so this week is excused. The streak kept going and no freeze was spent.": "아팠으니 이번 주는 인정돼요. 연속 기록은 이어졌고 동결권은 쓰지 않았어요.",
  "You were travelling, so this week is excused. The streak kept going and no freeze was spent.": "여행 중이었으니 이번 주는 인정돼요. 연속 기록은 이어졌고 동결권은 쓰지 않았어요.",
