  "{1} is still recovering, so it sits this one out.": "{1}은(는) 아직 회복 중이라 이번엔 쉬어요.",
  "And it stays that way: openGym Offline has no internet permission, so Android blocks anything it might try.": "앞으로도 그렇습니다. openGym Offline에는 인터넷 권한이 없어서 Android가 모든 시도를 막아요.",
  "Any of the sounds on your phone.": "휴대폰에 있는 아무 소리나.",
  "Back it up now and then in Settings, Data & backup. A file on your phone is the only copy there is.": "가끔 설정, 데이터 및 백업에서 백업하세요. 휴대폰의 파일이 유일한 사본이에요.",
  "Closing the app resets the count; the log never leaves the phone.": "앱을 닫으면 횟수가 초기화돼요. 기록은 휴대폰 밖으로 나가지 않아요.",
  "Counting since {0}, when the app started. Closing the app resets it; the log never leaves the phone.": "앱이 시작된 {0}부터 세는 중. 닫으면 초기화돼요. 기록은 휴대폰 밖으로 나가지 않아요.",
  "Each reminder can sound different, so you know which one it is before you look.": "알림마다 소리를 다르게 해서 보기 전에 어떤 알림인지 알 수 있어요.",
  "Everything this app asked the internet for, newest first. The address only, never what was in it.": "이 앱이 인터넷에 요청한 모든 것, 최신순. 주소만, 내용은 절대 아님.",
  "For reading mid-set without your glasses.": "세트 중에 안경 없이 읽기 좋게.",
  "Larger": "더 크게",
  "Last at {0}": "마지막 {0}",
  "Latest": "최근",
  "Less: no sliding, bouncing or snow. Things just appear.": "적게: 미끄러짐, 튕김, 눈 없음. 그냥 나타나요.",
  "Like the phone": "휴대폰 설정대로",
  "Mostly your own server, {0}, when there was something to sync.": "동기화할 게 있을 때 주로 내 서버 {0}.",
  "Motion": "움직임",
  "Network log": "네트워크 기록",
  "No map search in openGym Offline. Stand in your gym, tap Current location, done.": "openGym Offline에는 지도 검색이 없어요. 헬스장에 서서 현재 위치를 누르면 끝.",
  "Not a single byte left this phone. Your training is nobody’s business but yours.": "이 휴대폰에서 단 1바이트도 나가지 않았어요. 내 운동은 나만의 일이니까요.",
  "Nothing yet. Your server hears from this phone when there is something to sync.": "아직 없음. 동기화할 게 있을 때 서버가 이 휴대폰 소식을 들어요.",
  "Phone default": "휴대폰 기본값",
  "Phone sound": "휴대폰 소리",
  "Pick a phone sound…": "휴대폰 소리 고르기…",
  "Showing the last {0}. The count above has them all.": "최근 {0}개 표시 중. 위의 횟수에는 전부 들어 있어요.",
  "Shows up, keeps quiet.": "표시만 하고 조용히.",
  "Tap one to hear it. It rings even with the app closed.": "눌러서 들어 보세요. 앱이 닫혀 있어도 울려요.",
  "Text size": "글자 크기",
  "This is openGym Offline: Android doesn’t even let it on the internet. Want sync? The normal openGym app can do that, next to this one.": "이것은 openGym Offline이에요. Android가 인터넷에도 못 나가게 해요. 동기화가 필요하다면? 일반 openGym 앱이 할 수 있어요, 바로 옆에서.",
  "Weigh-ins, measurements and progress photos.": "체중, 신체 치수, 진행 사진.",
  "Whatever your phone uses for notifications.": "휴대폰이 알림에 쓰는 소리.",
  "When you walk into your gym.": "헬스장에 들어설 때.",
  "Who": "누구",
  "Who this app talked to since you opened it.": "앱을 연 뒤로 이 앱이 누구와 통신했는지.",
  "Workout days and the nudge when one slips by.": "운동하는 날, 그리고 하루 놓쳤을 때의 콕 찌르기.",
  "Workout reminders": "운동 알림",
  "openGym Offline has no internet permission. Your training stays on this phone, full stop.": "openGym Offline에는 인터넷 권한이 없어요. 운동 기록은 이 휴대폰에 남아요. 끝.",
  "openGym Offline never checks for updates, it can’t. New versions come from wherever you got this one.": "openGym Offline은 업데이트를 확인하지 않아요. 할 수가 없거든요. 새 버전은 이 앱을 받은 곳에 있어요.",
  "openGym Offline, no internet permission": "openGym Offline, 인터넷 권한 없음",
  "openGym Offline: on this phone, and only here": "openGym Offline: 이 휴대폰에만, 여기에만",
